-- WARNING: replaces demo data in the seven cinema_* databases. Stop services before running.
SET NAMES utf8mb4;
SET time_zone='+00:00';
SET @OLD_SQL_SAFE_UPDATES=@@SQL_SAFE_UPDATES;
SET SQL_SAFE_UPDATES=0;
START TRANSACTION;
DELETE FROM cinema_notification_db.notification;
DELETE FROM cinema_payment_db.payment;
DELETE FROM cinema_payment_db.payment_guard;
DELETE FROM cinema_booking_db.seat_reservation;
DELETE FROM cinema_booking_db.booking_seat;
DELETE FROM cinema_booking_db.booking;
DELETE FROM cinema_showtime_db.showtime;
DELETE FROM cinema_showtime_db.room_guard;
DELETE FROM cinema_cinema_db.seat;
DELETE FROM cinema_cinema_db.room;
DELETE FROM cinema_cinema_db.cinema;
DELETE FROM cinema_movie_db.movie_categories;
DELETE FROM cinema_movie_db.movie;
DELETE FROM cinema_movie_db.category;
DELETE FROM cinema_auth_db.users;
SET @user_0=LAST_INSERT_ID();
SET @user_1=LAST_INSERT_ID();
SET @user_2=LAST_INSERT_ID();
SET @cat_0=LAST_INSERT_ID();
SET @cat_1=LAST_INSERT_ID();
SET @cat_2=LAST_INSERT_ID();
SET @cat_3=LAST_INSERT_ID();
SET @cat_4=LAST_INSERT_ID();
SET @movie_0=LAST_INSERT_ID();
SET @movie_1=LAST_INSERT_ID();
SET @movie_2=LAST_INSERT_ID();
SET @movie_3=LAST_INSERT_ID();
SET @movie_4=LAST_INSERT_ID();
