SET @movie_6=LAST_INSERT_ID();
SET @movie_7=LAST_INSERT_ID();
SET @movie_8=LAST_INSERT_ID();
SET @movie_9=LAST_INSERT_ID();
SET @cinema_0=LAST_INSERT_ID();
SET @room_0=LAST_INSERT_ID();
SET @room_1=LAST_INSERT_ID();
SET @cinema_1=LAST_INSERT_ID();
SET @room_2=LAST_INSERT_ID();
SET @room_3=LAST_INSERT_ID();
SET @cinema_2=LAST_INSERT_ID();
SET @room_4=LAST_INSERT_ID();
SET @room_5=LAST_INSERT_ID();
SET @demo_showtime=LAST_INSERT_ID();
SET @demo_room=(SELECT room_id FROM cinema_showtime_db.showtime WHERE id=@demo_showtime);
SET @snapshot=(SELECT JSON_OBJECT('showtime',JSON_OBJECT('id',s.id,'movieId',s.movie_id,'cinemaId',s.cinema_id,'roomId',s.room_id,'showDate',DATE_FORMAT(s.show_date,'%Y-%m-%d'),'startTime',TIME_FORMAT(s.start_time,'%H:%i:%s'),'basePrice',s.base_price),'movie',JSON_OBJECT('id',m.id,'title',m.title,'posterUrl',m.poster_url),'cinema',JSON_OBJECT('id',c.id,'name',c.name),'room',JSON_OBJECT('id',r.id,'name',r.name)) FROM cinema_showtime_db.showtime s JOIN cinema_movie_db.movie m ON m.id=s.movie_id JOIN cinema_cinema_db.cinema c ON c.id=s.cinema_id JOIN cinema_cinema_db.room r ON r.id=s.room_id WHERE s.id=@demo_showtime);
SET @booking_0=LAST_INSERT_ID();
SET @seat=(SELECT id FROM cinema_cinema_db.seat WHERE room_id=@demo_room AND row_name='B' AND seat_number=1);
SET @booking_1=LAST_INSERT_ID();
SET @seat=(SELECT id FROM cinema_cinema_db.seat WHERE room_id=@demo_room AND row_name='B' AND seat_number=2);
SET @booking_2=LAST_INSERT_ID();
SET @seat=(SELECT id FROM cinema_cinema_db.seat WHERE room_id=@demo_room AND row_name='B' AND seat_number=3);
SET @booking_3=LAST_INSERT_ID();
SET @seat=(SELECT id FROM cinema_cinema_db.seat WHERE room_id=@demo_room AND row_name='B' AND seat_number=4);
COMMIT;
SET SQL_SAFE_UPDATES=@OLD_SQL_SAFE_UPDATES;
